package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService handles user-related business logic
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

// GetUserByID returns a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"fmt"
	"net/http"

	"legacy_refactor/internal/service"
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	userService *service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s *service.UserService) *UserHandler {
	return &UserHandler{
		userService: s,
	}
}

// HandleUsers manages requests to /users
func (h *UserHandler) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID manages requests to /users/{id}
func (h *UserHandler) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		h.GetUser(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUsers handles GET requests for all users
func (h *UserHandler) GetUsers(w http.ResponseWriter, r *http.Request) {
	users := h.userService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST requests to create a new user
func (h *UserHandler) CreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.userService.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUser handles GET requests for a single user by ID
func (h *UserHandler) GetUser(w http.ResponseWriter, r *http.Request, id string) {
	user, ok := h.userService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"legacy_refactor/internal/api"
	"legacy_refactor/internal/service"
)

func main() {
	// Initialize service and handlers
	userService := service.NewUserService()
	userHandler := api.NewUserHandler(userService)

	// Register HTTP routes
	http.HandleFunc("/users", userHandler.HandleUsers)
	http.HandleFunc("/users/", userHandler.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"testing"

	"rep-1/internal/service"
	"github.com/stretchr/testify/assert"
)

func TestNewUserService(t *testing.T) {
	s := service.NewUserService()
	assert.NotNil(t, s)
}

func TestCreateUser(t *testing.T) {
	s := service.NewUserService()

	user := service.User{Name: "John Doe", Email: "john@example.com"}
	createdUser, err := s.CreateUser(user)
	assert.NoError(t, err)
	assert.NotEmpty(t, createdUser.ID)
	assert.Equal(t, user.Name, createdUser.Name)
	assert.Equal(t, user.Email, createdUser.Email)

	// Verify user is in the system
	retrievedUser, ok := s.GetUserByID(createdUser.ID)
	assert.True(t, ok)
	assert.Equal(t, createdUser, retrievedUser)
}

func TestGetAllUsers(t *testing.T) {
	s := service.NewUserService()

	user1 := service.User{Name: "John Doe", Email: "john@example.com"}
	user2 := service.User{Name: "Jane Smith", Email: "jane@example.com"}

	s.CreateUser(user1)
	s.CreateUser(user2)

	allUsers := s.GetAllUsers()
	assert.Len(t, allUsers, 2)

	// Check if users are present (order doesn't matter for GetAll)
	foundJohn := false
	foundJane := false
	for _, u := range allUsers {
		if u.Name == "John Doe" {
			foundJohn = true
		}
		if u.Name == "Jane Smith" {
			foundJane = true
		}
	}
	assert.True(t, foundJohn)
	assert.True(t, foundJane)
}

func TestGetUserByID(t *testing.T) {
	s := service.NewUserService()

	user := service.User{Name: "John Doe", Email: "john@example.com"}
	createdUser, _ := s.CreateUser(user)

	// Test existing user
	retrievedUser, ok := s.GetUserByID(createdUser.ID)
	assert.True(t, ok)
	assert.Equal(t, createdUser, retrievedUser)

	// Test non-existing user
	_, ok = s.GetUserByID("non-existent-id")
	assert.False(t, ok)
}

package api_test

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"rep-1/internal/api"
	"rep-1/internal/service"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
)

// MockUserService is a mock implementation of service.UserService
type MockUserService struct {
	mock.Mock
}

func (m *MockUserService) GetAllUsers() []service.User {
	args := m.Called()
	return args.Get(0).([]service.User)
}

func (m *MockUserService) CreateUser(user service.User) (service.User, error) {
	args := m.Called(user)
	return args.Get(0).(service.User), args.Error(1)
}

func (m *MockUserService) GetUserByID(id string) (service.User, bool) {
	args := m.Called(id)
	return args.Get(0).(service.User), args.Bool(1)
}

func TestUserHandler_GetUsers(t *testing.T) {
	mockService := new(MockUserService)
	expectedUsers := []service.User{
		{ID: "1", Name: "John Doe", Email: "john@example.com"},
		{ID: "2", Name: "Jane Smith", Email: "jane@example.com"},
	}
	mockService.On("GetAllUsers").Return(expectedUsers)

	handler := api.NewUserHandler(mockService)

	req := httptest.NewRequest(http.MethodGet, "/users", nil)
	rr := httptest.NewRecorder()

	handler.GetUsers(rr, req)

	assert.Equal(t, http.StatusOK, rr.Code)

	var actualUsers []service.User
	err := json.NewDecoder(rr.Body).Decode(&actualUsers)
	assert.NoError(t, err)
	assert.Equal(t, expectedUsers, actualUsers)
	mockService.AssertExpectations(t)
}

func TestUserHandler_CreateUser(t *testing.T) {
	mockService := new(MockUserService)
	newUser := service.User{Name: "John Doe", Email: "john@example.com"}
	createdUser := service.User{ID: "uuid-123", Name: "John Doe", Email: "john@example.com"}
	mockService.On("CreateUser", newUser).Return(createdUser, nil)

	handler := api.NewUserHandler(mockService)

	requestBody, _ := json.Marshal(newUser)
	req := httptest.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(requestBody))
	rr := httptest.NewRecorder()

	handler.CreateUser(rr, req)

	assert.Equal(t, http.StatusCreated, rr.Code)

	var actualUser service.User
	err := json.NewDecoder(rr.Body).Decode(&actualUser)
	assert.NoError(t, err)
	assert.Equal(t, createdUser, actualUser)
	mockService.AssertExpectations(t)
}

func TestUserHandler_GetUser(t *testing.T) {
	mockService := new(MockUserService)
	expectedUser := service.User{ID: "1", Name: "John Doe", Email: "john@example.com"}
	mockService.On("GetUserByID", "1").Return(expectedUser, true)

	handler := api.NewUserHandler(mockService)

	req := httptest.NewRequest(http.MethodGet, "/users/1", nil)
	rr := httptest.NewRecorder()

	handler.GetUser(rr, req, "1")

	assert.Equal(t, http.StatusOK, rr.Code)

	var actualUser service.User
	err := json.NewDecoder(rr.Body).Decode(&actualUser)
	assert.NoError(t, err)
	assert.Equal(t, expectedUser, actualUser)
	mockService.AssertExpectations(t)
}

func TestUserHandler_GetUser_NotFound(t *testing.T) {
	mockService := new(MockUserService)
	mockService.On("GetUserByID", "non-existent").Return(service.User{}, false)

	handler := api.NewUserHandler(mockService)

	req := httptest.NewRequest(http.MethodGet, "/users/non-existent", nil)
	rr := httptest.NewRecorder()

	handler.GetUser(rr, req, "non-existent")

	assert.Equal(t, http.StatusNotFound, rr.Code)
	mockService.AssertExpectations(t)
}

